#!/usr/bin/env bash
# Regenerates amax_today_ref.sv: the qfd_dv_slice2 LM-head running-argmax block (lines 199-234) copied verbatim.
set -eu
H=$(cd "$(dirname "$0")" && pwd); R=$H/../../../../rtl/qwen_dv/qfd_dv_slice2.sv
grep -q 'LM-head running argmax (max, lowest index)' <(sed -n 199p "$R") || { echo "slice2 block moved"; exit 1; }
{ cat <<'H1'
`timescale 1ns/1ps
// Reference: the LM-head running-argmax block of rtl/qwen_dv/qfd_dv_slice2.sv (origin/main), lines 199-234, copied
// VERBATIM between the markers (generated by mk_ref.sh); only the port list around it is added.  tb_amax_mu.sv drives
// it and qfd_dv_amax_mu #(.NU(1)) with the same random stimulus and requires every output equal on every edge.
module amax_today_ref (
    input  wire ck, input wire rst, input wire c_stn, input wire [115:0] cmd_q, input wire go, input wire [2:0] kind,
    input  wire r_v, input wire [23:0] r_addr, input wire [511:0] r_d,
    output wire am_v, output wire [23:0] am_idx, output wire [31:0] am_val, output wire emit_empty);
// ---- verbatim begin
H1
sed -n 199,234p "$R"
cat <<'H2'
// ---- verbatim end
    assign emit_empty = am_emit && !am_run[56];
endmodule
H2
} > "$H/amax_today_ref.sv"
